contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address callee) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint256 cBalanceBefore = address(c).balance;
        uint256 thisBalanceBefore = address(this).balance;

        bool reverted;
        c.forward(callee, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 cBalanceAfter = address(c).balance;
        uint256 thisBalanceAfter = address(this).balance;

        assert(!reverted || (cBalanceAfter == cBalanceBefore && thisBalanceAfter == thisBalanceBefore));
    }

    receive() external payable {}
}

